INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "梁王在贝州休兵", "start_year": 907, "end_year": 907, "time_original": "唐天祐四年正月辛巳", "dynasty": "唐末五代十国", "description": "《通鉴》记梁王在贝州休兵。", "phases": [], "location_name": "贝州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "00718a7a-736a-5540-a19c-ecaeb85c82e0"}, {"title": "张颢、徐温发动兵谏，控制淮南军政", "start_year": 907, "end_year": 907, "time_original": "唐天祐四年正月（原文干支作丙戍，待校）", "dynasty": "唐末五代十国", "description": "张颢、徐温率牙兵进入杨渥治事之所，杀其亲信，并逐步控制军政。诛杀三将等前事的具体日期未详。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "75b940f5-52c3-50b3-887c-2d55ad65c36c"}, {"title": "罗绍威劝梁王灭唐，薛贻矩往返传达禅位意向", "start_year": 907, "end_year": 907, "time_original": "唐天祐四年正月", "dynasty": "唐末五代十国", "description": "罗绍威劝梁王尽早灭唐；唐昭宣帝遣薛贻矩至大梁，薛归后报告梁王有受禅之意，唐帝随后提出禅位，梁王辞让。", "phases": [], "location_name": "魏、大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "d65b4d3d-5c8f-5105-bcfd-1633778ed244"}, {"title": "康怀贞奉命屯晋州防备河东军", "start_year": 907, "end_year": 907, "time_original": "唐天祐四年正月条，具体日未载", "dynasty": "唐末五代十国", "description": "梁王命康怀贞征发京兆、同华之兵屯晋州，以防备欲进攻泽州的河东军。", "phases": [], "location_name": "晋州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "035ecc98-3eef-53e7-8c05-2493bfc68957"}, {"title": "唐廷与各镇相继向梁王劝进", "start_year": 907, "end_year": 907, "time_original": "唐天祐四年二月至三月", "dynasty": "唐末五代十国", "description": "唐廷组织百官劝进，三月再遣使传达禅位之意，并安排册礼、传国宝与金宝的奉送人员。杨凝式劝父杨涉辞去送玺之事。", "phases": [], "location_name": "大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "0ca868ec-69c8-5cb8-81c7-96f889349aab"}, {"title": "李思安进攻幽州，被刘守光击退", "start_year": 907, "end_year": 907, "time_original": "唐天祐四年三月至四月己酉", "dynasty": "唐末五代十国", "description": "李思安奉梁王命领兵进攻幽州。四月抵城时刘仁恭不在城中，刘守光入城拒守并击退李思安。", "phases": [], "location_name": "幽州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "fd713cf1-2518-5245-bb40-1fc7ade58200"}, {"title": "刘守光夺取卢龙军权并囚禁刘仁恭", "start_year": 907, "end_year": 907, "time_original": "唐天祐四年四月条", "dynasty": "唐末五代十国", "description": "刘守光击退李思安后自称节度使，遣李小喜、元行钦进攻大安山，擒获并囚禁父亲刘仁恭。", "phases": [], "location_name": "幽州、大安山", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "22048b33-cfe1-5c36-a174-6cac13729ef7"}, {"title": "王思同、李承约等离开幽州投奔河东", "start_year": 907, "end_year": 907, "time_original": "唐天祐四年四月条，先后间隔未详", "dynasty": "唐末五代十国", "description": "刘守光夺权后，王思同、李承约率部投奔河东；刘守奇先奔契丹，后亦奔河东。李克用任命李承约与王思同。", "phases": [], "location_name": "河东", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "680a4b8a-83ef-57ac-86e5-4f6b95143d3b"}, {"title": "钱氏军队攻取温州，卢佶被杀", "start_year": 907, "end_year": 907, "time_original": "907年正月至四月（吴越备史记正月出兵，通鉴记三月出兵；四月取温州）", "dynasty": "唐末五代十国", "description": "钱镠遣钱传镣、钱传瓘讨卢佶。钱传瓘避开青澳守军，自安固取道袭温州，城破后卢佶被擒杀；吴璋受命处理温州事务，钱氏军队转攻处州。", "phases": [], "location_name": "温州、青澳、安固", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "7a6b4f25-ef47-587b-8117-559fb13360bb"}, {"title": "梁王受百官称臣，下令公文去唐年号", "start_year": 907, "end_year": 907, "time_original": "唐天祐四年四月庚戌、辛亥", "dynasty": "唐末五代十国", "description": "梁王在金祥殿受百官称臣，随后令笺表簿籍去除唐年号，仅记月日。", "phases": [], "location_name": "金祥殿", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "68302e6d-1846-562c-97c5-ddef4dc41044"}, {"title": "朱温在即位前更名晃", "start_year": 907, "end_year": 907, "time_original": "唐天祐四年四月壬戌", "dynasty": "唐末五代十国", "description": "梁王在即位前更名晃；原文并记其兄朱全昱对称帝提出质问。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "9fa88b8f-8d2e-5e3a-b35b-15808df5a632"}, {"title": "朱温称帝，后梁建立", "start_year": 907, "end_year": 907, "time_original": "唐天祐四年／梁开平元年四月甲子即位、戊辰改元国号", "dynasty": "后梁", "description": "朱温在大梁即皇帝位，随后改元开平，国号大梁；唐昭宣帝被降为济阴王。汴州升为开封府、号东都。后梁建立并未使各地割据政权随之消失。", "phases": [], "location_name": "大梁（金祥殿）", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "1047bb1e-a052-5199-9709-9bede79f6af2"}, {"title": "后梁封马殷为楚王", "start_year": 907, "end_year": 907, "time_original": "梁开平元年四月辛未", "dynasty": "唐末五代十国", "description": "后梁以武安节度使马殷为楚王。封号不等于后梁实际直接控制其辖地。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "8cf57a60-57f4-577f-bbdc-951e4aafe44d"}, {"title": "敬翔主持崇政院，枢密院职事并入", "start_year": 907, "end_year": 907, "time_original": "梁开平元年四月至五月甲午", "dynasty": "唐末五代十国", "description": "敬翔先知崇政院事，负责承宣旨意及顾问谋议；五月后梁废枢密院，职事并入崇政院，以敬翔为院使。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "dcb44f0b-d6c9-58ab-aae0-0ae44f0d4d55"}, {"title": "朱温追尊先祖及父母", "start_year": 907, "end_year": 907, "time_original": "907年（追尊及相关礼仪分阶段记载，各书系月有异）", "dynasty": "唐末五代十国", "description": "朱温追尊高祖以来的先人，尊父朱诚为烈祖文穆皇帝，母王氏为文惠皇后。追尊发生于先人去世之后。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "41008971-04ea-5e8f-8bd0-2aa02eabcdde"}, {"title": "朱友文出任开封尹并主持建昌院", "start_year": 907, "end_year": 907, "time_original": "梁开平元年四月至五月辛卯", "dynasty": "唐末五代十国", "description": "朱温以养子朱友文为开封尹、判建昌院事，掌财政事务。五月建昌院改为建昌宫，相关职名随之改为建昌宫使。", "phases": [], "location_name": "开封", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "044e351e-d4e5-5811-96a8-601d833751e9"}, {"title": "后梁削夺李克用官爵", "start_year": 907, "end_year": 907, "time_original": "梁开平元年四月乙亥", "dynasty": "唐末五代十国", "description": "后梁下制削夺李克用官爵。原文同时记河东等地仍用唐年号，显示各地对后梁正朔的接受并不一致。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "5a40eb5a-534e-5998-a47b-5c771992120f"}, {"title": "蜀王与晋王讨论讨梁及称帝", "start_year": 907, "end_year": 907, "time_original": "907年后梁建立后条，具体日期未载", "dynasty": "唐末五代十国", "description": "蜀王致书晋王，提出各帝一方、平梁后再立唐宗室；李克用回书不许。此为书信提议，不能据此认定双方已结成军事同盟。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "6782cad6-c288-5916-963c-dba6b6c72440"}, {"title": "李克用复用张承业为监军", "start_year": 907, "end_year": 907, "time_original": "907年后梁建立后条，具体日期未载", "dynasty": "唐末五代十国", "description": "李克用重新任用张承业为监军。段首保护张承业之事属于唐末追叙，不定为907年新事件。", "phases": [], "location_name": "河东", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "ff7d2895-af9b-5e1a-9e58-408db8f80d80"}, {"title": "岐王在唐亡后开府置百官", "start_year": 907, "end_year": 907, "time_original": "907年闻唐亡后，具体日期未载", "dynasty": "唐末五代十国", "description": "岐王在唐亡后没有称帝，但开府置百官，多项礼仪仿照帝制。段首有关治军的轶事不强行断为本年。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "a611cfa4-e1e8-5520-879a-d4dddf826ae0"}, {"title": "罗隐劝钱镠讨梁，钱镠未采纳", "start_year": 907, "end_year": 907, "time_original": "907年后梁建立后条，具体日期未载", "dynasty": "唐末五代十国", "description": "罗隐劝钱镠出兵讨梁；原文记钱镠未能采用该建议。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "691b6d3c-a4ad-5313-b477-bfd3fe435a30"}, {"title": "薛贻矩出任中书侍郎、同平章事", "start_year": 907, "end_year": 907, "time_original": "梁开平元年五月丁丑朔", "dynasty": "唐末五代十国", "description": "后梁以薛贻矩为中书侍郎、同平章事。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "7f037028-1cb0-540b-8a42-3fc2671273b7"}, {"title": "后梁加授王镕、罗绍威、王处直官衔", "start_year": 907, "end_year": 907, "time_original": "梁开平元年五月条，具体日未载", "dynasty": "唐末五代十国", "description": "后梁加授王镕、罗绍威、王处直官衔。所据文本“王镕宁太师”有疑字，具体官衔待考。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "9d9135d7-89d5-5d3a-94cf-cb1b7d60cfeb"}, {"title": "契丹与后梁互遣使者通好", "start_year": 907, "end_year": 907, "time_original": "907年后梁建立后（通鉴系五月条，新五代史系四月条）", "dynasty": "唐末五代十国", "description": "契丹遣袍笏梅老通好，后梁遣高颀回访。契丹沿革及此前会盟不属于此次使行。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "e0b379cb-4573-54fd-899c-5b100698019d"}, {"title": "后梁加封钱镠、张全义、刘隐等", "start_year": 907, "end_year": 907, "time_original": "梁开平元年五月己卯", "dynasty": "唐末五代十国", "description": "后梁封张全义为魏王、钱镠为吴越王；加刘隐、王审知兼侍中，封刘隐为大彭王。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "ba18f771-e163-5b40-837f-ffbd572978b9"}, {"title": "高季昌受命为荆南节度使", "start_year": 907, "end_year": 907, "time_original": "梁开平元年五月癸未", "dynasty": "唐末五代十国", "description": "后梁以高季昌为荆南节度使；原文记其到任后安集流散人口。江陵的恢复并非一日完成。", "phases": [], "location_name": "荆南、江陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "727305cf-fa90-5394-b0ce-23c8c9000212"}, {"title": "后梁封朱全昱及诸子为王", "start_year": 907, "end_year": 907, "time_original": "梁开平元年五月乙酉", "dynasty": "唐末五代十国", "description": "后梁封朱全昱为广王，朱友文为博王、朱友珪为郢王、朱友璋为福王、朱友贞为均王、朱友雍为贺王、朱友徽为建王；朱友文的养子身份另据前文记录。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "72c2f039-6e8c-5dd4-919d-18ea3dcb3d06"}, {"title": "梁军围攻潞州，晋军出兵救援", "start_year": 907, "end_year": 907, "time_original": "梁开平元年五月至六月条", "dynasty": "唐末五代十国", "description": "康怀贞奉命攻潞州；李嗣昭、李嗣弼守城。梁军久攻不克，转为筑垒围困；李克用命周德威等救援。这是907年围城与救援，与既有908年解围事件分别记录。", "phases": [], "location_name": "潞州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "0f2867e2-991b-5ba8-8507-ecf77ab7dc82"}, {"title": "后梁勒令苏循、张祎等致仕", "start_year": 907, "end_year": 907, "time_original": "梁开平元年五月（干支原文作戊戍，待校）", "dynasty": "唐末五代十国", "description": "后梁勒令苏循、张祎等十五人致仕，将苏楷斥归田里；苏循父子后依朱友谦。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "e82aad47-9dce-5ea9-a484-5c7f51434c0e"}, {"title": "卢约以处州归降吴越", "start_year": 907, "end_year": 907, "time_original": "907年五月条，具体日未载", "dynasty": "唐末五代十国", "description": "卢约以处州归降吴越。", "phases": [], "location_name": "处州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "4c289f76-c02b-53f6-b7e2-60fa9c8f0704"}, {"title": "楚军击败刘存等淮南水军，攻取岳州", "start_year": 907, "end_year": 907, "time_original": "907年五月出兵、六月交战", "dynasty": "唐末五代十国", "description": "杨渥遣刘存等攻楚；秦彦晖、黄璠合击淮南军，刘存、陈知新被俘后遭马殷处死，刘威退走。秦彦晖随后取岳州。", "phases": [], "location_name": "越堤、浏阳口、岳州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "237c5da4-1431-57f9-bbe6-7b4ac433142b"}, {"title": "张颢、徐温在败战后处死许玄应", "start_year": 907, "end_year": 907, "time_original": "907年六月败战后，具体日未载", "dynasty": "唐末五代十国", "description": "淮南军攻楚失败后，张颢、徐温收捕并处死弘农王腹心许玄应。与战场上处死刘存、陈知新分开记录。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "a7daea15-5d12-52ee-a826-02e35522ffd7"}, {"title": "楚军与彭玕进攻洪州未克", "start_year": 907, "end_year": 907, "time_original": "907年六月条，具体日未载", "dynasty": "唐末五代十国", "description": "马殷遣军与吉州刺史彭玕会攻洪州，未能攻克。", "phases": [], "location_name": "洪州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "653874bc-a2b2-504c-a375-e81d566bfaf1"}, {"title": "范居实奉命救援泽州", "start_year": 907, "end_year": 907, "time_original": "梁开平元年六月条，具体日未载", "dynasty": "唐末五代十国", "description": "晋军攻泽州，后梁遣范居实领兵救援。", "phases": [], "location_name": "泽州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "d2f71797-3dcf-545a-93b6-b88d2cab065b"}, {"title": "韩建出任司徒、同平章事", "start_year": 907, "end_year": 907, "time_original": "梁开平元年六月甲寅", "dynasty": "唐末五代十国", "description": "后梁以平卢节度使韩建守司徒、同平章事。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "e147b81c-4843-5ab2-af3e-f5ec7fc86954"}, {"title": "高季昌断粮击退雷彦恭与楚军", "start_year": 907, "end_year": 907, "time_original": "907年六月条，具体日未载", "dynasty": "唐末五代十国", "description": "雷彦恭与楚军进攻江陵，高季昌屯公安并切断对方粮道，雷彦恭败退，楚军亦退。", "phases": [], "location_name": "江陵、公安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "3d889160-d4c4-5d63-9a81-e1eaeb7214fb"}, {"title": "后梁授刘守光卢龙节度使", "start_year": 907, "end_year": 907, "time_original": "梁开平元年七月甲午", "dynasty": "唐末五代十国", "description": "刘守光囚父、自称留后后向后梁请命，获授卢龙节度使、同平章事。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "e8178458-0df1-5659-bed2-a9a835faf195"}, {"title": "曲颢继曲裕为静海节度使", "start_year": 907, "end_year": 907, "time_original": "梁开平元年七月丙申", "dynasty": "唐末五代十国", "description": "曲裕死后，其子曲颢由权知留后受命为静海节度使。人名沿用《通鉴》记载，异名待考。", "phases": [], "location_name": "静海", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "1a7cf851-fcd8-5ae7-81e7-ea7a251b80f3"}, {"title": "雷彦恭进攻岳州未克", "start_year": 907, "end_year": 907, "time_original": "907年七月条，具体日未载", "dynasty": "唐末五代十国", "description": "雷彦恭进攻岳州，未能攻克。", "phases": [], "location_name": "岳州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "bcb1840b-829e-5f36-a356-ae784f0a6138"}, {"title": "后梁赐张全义名宗奭", "start_year": 907, "end_year": 907, "time_original": "梁开平元年八月丙午", "dynasty": "唐末五代十国", "description": "后梁赐河南尹张全义名宗奭。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "61df11d1-cd07-5766-b027-d5883400fa34"}, {"title": "后梁令钱镠、马殷兼领淮南与武昌军职", "start_year": 907, "end_year": 907, "time_original": "梁开平元年八月辛亥", "dynasty": "唐末五代十国", "description": "后梁以钱镠兼淮南节度使、马殷兼武昌节度使，并授招讨制置职任。这里只记录授官，不表示二人已实际占有对应辖区。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "d48c8af9-aa4c-57aa-a21e-f653ab35c76d"}, {"title": "周德威在高河击败秦武", "start_year": 907, "end_year": 907, "time_original": "907年八月条，具体日未载", "dynasty": "唐末五代十国", "description": "康怀贞遣秦武进攻屯高河的周德威，秦武战败。", "phases": [], "location_name": "高河", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "1bde1204-9872-5199-ae9c-c8d8e304bcc0"}, {"title": "李思安接掌潞州围军，修筑夹寨", "start_year": 907, "end_year": 907, "time_original": "梁开平元年八月（干支原文作丁已，待校）", "dynasty": "唐末五代十国", "description": "李思安代康怀贞为潞州行营都统，修筑内外夹城及运粮甬道。周德威等反复袭扰，使梁军受困。", "phases": [], "location_name": "潞州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "56594a8a-4634-5611-84a9-d3a5ff9675f4"}, {"title": "雷彦恭再攻荆南失利，被后梁削爵讨伐", "start_year": 907, "end_year": 907, "time_original": "梁开平元年九月丙申及此前", "dynasty": "唐末五代十国", "description": "雷彦恭进攻涔阳、公安，被高季昌击退。后梁削其官爵，命高季昌与马殷讨伐。", "phases": [], "location_name": "涔阳、公安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "c9db70c7-1fed-5af8-a739-b0b2c472d3ab"}, {"title": "王建称帝，建立前蜀", "start_year": 907, "end_year": 907, "time_original": "907年九月己亥", "dynasty": "唐末五代十国", "description": "王建未采用冯涓建议称制的意见，采韦庄之谋称帝，国号大蜀；史称前蜀。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "fe13c8b8-7b97-5141-bde8-b2e496f0b1c9"}, {"title": "前蜀任命王宗佶、韦庄、唐道袭", "start_year": 907, "end_year": 907, "time_original": "907年九月辛丑", "dynasty": "唐末五代十国", "description": "王建称帝后任命王宗佶为中书令、韦庄判中书门下事、唐道袭为内枢密使；并封王宗懿为遂王，封王具体日未载。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "a8b0614b-8e01-55bf-8de3-f52ed0feda35"}, {"title": "荆南、楚军攻朗州，许德勋击败淮南援军", "start_year": 907, "end_year": 907, "time_original": "907年十月", "dynasty": "唐末五代十国", "description": "高季昌遣倪可福会秦彦晖攻朗州。杨渥遣泠业、李饶救雷彦恭，马殷遣许德勋迎击；淮南援军战败，泠业、李饶被俘后在长沙处死。", "phases": [], "location_name": "朗州、朗口、浏阳、长沙", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "dd736a34-d63a-59b3-91e7-d10c3e267765"}, {"title": "尹皓攻取晋军江猪岭寨", "start_year": 907, "end_year": 907, "time_original": "梁开平元年十一月甲申", "dynasty": "唐末五代十国", "description": "夹马指挥使尹皓攻取晋军江猪岭寨。", "phases": [], "location_name": "江猪岭寨", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "e4d42907-4f57-5521-ae13-b1cb1399f2bb"}, {"title": "刘守文起兵攻打刘守光", "start_year": 907, "end_year": 907, "time_original": "907年十一月条，具体日未载", "dynasty": "唐末五代十国", "description": "刘守文得知弟弟刘守光囚父后起兵进攻，双方互有胜负。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "4470dce0-0e2b-5c1f-8f31-b2b7897d1652"}, {"title": "罗绍威劝刘守文归梁，刘延祐入质", "start_year": 907, "end_year": 907, "time_original": "梁开平元年十一月戊子", "dynasty": "唐末五代十国", "description": "罗绍威致书刘守文劝其归梁。刘守文遣使请降，送子刘延祐为质；后梁加授其中书令。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "467cee9e-49ef-5b6e-a56c-b22fc21411f2"}, {"title": "后梁赦免逃亡军士，许文面者还乡", "start_year": 907, "end_year": 907, "time_original": "梁开平元年十一月壬寅", "dynasty": "唐末五代十国", "description": "后梁赦免逃亡军士，允许有军号刺字者还乡。此前跋队斩和刺字制度为段首追叙，不作为本年新设制度。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "abb7f5d9-9f17-5bc2-a219-9ea5b59a5b22"}, {"title": "米志诚袭颍州，梁援军出动后退兵", "start_year": 907, "end_year": 907, "time_original": "907年十一月至十二月甲子", "dynasty": "唐末五代十国", "description": "米志诚率淮南军攻取颍州外郭，张实守子城。后梁十二月发援军，米志诚等退兵。", "phases": [], "location_name": "颍州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "ccb109d3-0568-51d4-b469-bccfcd8447ce"}, {"title": "李存璋攻晋州，后梁令河中、陕州救援", "start_year": 907, "end_year": 907, "time_original": "907年十一月至十二月壬戌", "dynasty": "唐末五代十国", "description": "李克用命李存璋攻晋州，以分散上党方面的梁军；后梁命河中、陕州出兵救援。", "phases": [], "location_name": "晋州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "ae19efb9-c6a0-5abe-8dae-cb89db82f5cd"}, {"title": "晋军进攻洺州", "start_year": 907, "end_year": 907, "time_original": "907年十二月丁卯", "dynasty": "唐末五代十国", "description": "《通鉴》记晋军进攻洺州，未在此段指明具体领兵者。", "phases": [], "location_name": "洺州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "6c505c30-5bc1-5481-82b6-8616e432ad83"}, {"title": "淮南军攻信州，危仔倡向吴越求援", "start_year": 907, "end_year": 907, "time_original": "907年十二月条，具体日未载", "dynasty": "唐末五代十国", "description": "淮南军进攻信州，刺史危仔倡向吴越求援。", "phases": [], "location_name": "信州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "fda324ee-3802-57b1-937c-5bc3f3b9d06c"}, {"title": "张文蔚、杨涉留任宰相", "start_year": 907, "end_year": 907, "time_original": "梁开平元年五月", "dynasty": "唐末五代十国", "description": "后梁以唐朝宰臣张文蔚、杨涉为门下侍郎、平章事；这是政权更替后的官职延续。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "7a89e6a4-834f-5498-a545-d16286e858ec"}, {"title": "后梁诏复唐朝被贬官员官资", "start_year": 907, "end_year": 907, "time_original": "梁开平元年六月癸亥", "dynasty": "唐末五代十国", "description": "后梁下诏登记唐朝被贬南方官员姓名，恢复官资并送赴京师；已死者准许归葬。诏令在各地的实际执行情况未详。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "3ac43655-b429-58ba-b650-fa400c50a5a9"}, {"title": "后梁放出西京宫人", "start_year": 907, "end_year": 907, "time_original": "梁开平元年九月辛丑", "dynasty": "唐末五代十国", "description": "《旧五代史》记西京大内放出两宫内人及前朝宫人，任其所适；人数及此后去向未详。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "3e342aa0-d1da-53d9-bd7b-8be76f7df429"}, {"title": "后梁规定使臣停留期限", "start_year": 907, "end_year": 907, "time_original": "梁开平元年九月条，具体日未单列", "dynasty": "唐末五代十国", "description": "后梁针对奉使官员长期滞留，按各地距离规定一月、二十日、十日或三五日等停留期限，旅途日行两驿；疾病、江河阻隔须奏报，由御史纠察。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "528c48ca-aa6e-5fbe-8c41-9b166b18d7f1"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person_relationship (id, person_a, person_b, relation_type, description, status)
SELECT id, person_a, person_b, relation_type, description, status FROM jsonb_populate_recordset(NULL::public.person_relationship, '[{"relation_type": "父亲", "description": "钱镠为钱传镣之父。原文见907年条；不据此推导持续政治支持。", "status": "draft", "id": "020e2161-fd37-5714-8351-abbffa6ded93", "person_a": "d61d1f96-7af5-5367-8be8-7a25ee7c85ae", "person_b": "f60bd16f-d140-5eac-9e99-07baa2f10554"}, {"relation_type": "父亲", "description": "钱镠为钱传瓘之父。原文见907年条；不据此推导持续政治支持。", "status": "draft", "id": "78a83bc8-9817-50a6-a6d8-ed5235f56a25", "person_a": "d61d1f96-7af5-5367-8be8-7a25ee7c85ae", "person_b": "6674e6a1-d66d-5e57-af1f-2d98f55021a1"}, {"relation_type": "父亲", "description": "杨涉为杨凝式之父。原文见907年条；不据此推导持续政治支持。", "status": "draft", "id": "7e2a1667-3dfe-5d95-a09a-cb518ecd194b", "person_a": "c9b92d0c-0c86-500d-abe2-e727fde2814f", "person_b": "eba7c533-e1be-58ce-bda6-5310eeaf4372"}, {"relation_type": "父亲", "description": "刘仁恭为刘守光之父。原文见907年条；不据此推导持续政治支持。", "status": "draft", "id": "325c21ef-67ec-54c1-92d7-79f762f082a2", "person_a": "b8f07571-c891-57ce-b69c-3e4a58148227", "person_b": "ac08fec2-882c-537a-883f-b967e61fb335"}, {"relation_type": "父亲", "description": "苏循为苏楷之父。原文见907年条；不据此推导持续政治支持。", "status": "draft", "id": "4dda00ba-8a45-52a8-919b-9deb03c0473a", "person_a": "1e278e55-eb5a-585d-a426-e15cb2aa9a93", "person_b": "6ad02417-35fe-52d1-aa6d-2491ea690050"}, {"relation_type": "父亲", "description": "曲裕为曲颢之父。原文见907年条；不据此推导持续政治支持。", "status": "draft", "id": "9921078c-0c34-592d-a67a-16db4907c6f6", "person_a": "0a3543bb-70e2-577f-a25d-5280e470d697", "person_b": "70211e56-cad1-5f96-9e6f-9bcbb77941f5"}, {"relation_type": "父亲", "description": "刘守文为刘延祐之父。原文见907年条；不据此推导持续政治支持。", "status": "draft", "id": "965782c1-36a0-5d40-9ece-1a32965d0aa7", "person_a": "8d818778-5c92-5bc7-aa3e-0a5887582536", "person_b": "91a7085b-ad5f-532b-b327-72cb9fe94e52"}, {"relation_type": "父亲", "description": "王建为王宗懿之父。原文见907年条；不据此推导持续政治支持。", "status": "draft", "id": "07649800-62dd-52ec-8ab9-a12d78841e48", "person_a": "b02193d6-1c17-5154-bb7c-3295ed8dbbec", "person_b": "24619c01-3aaf-552b-9b0d-21046b17d893"}, {"relation_type": "父亲", "description": "朱温为朱友璋之父。原文见907年条；不据此推导持续政治支持。", "status": "draft", "id": "dd8a50f5-c19c-5624-a90f-ed8dfeb194f9", "person_a": "0555e455-34d4-54ef-b93e-b0e6425018ab", "person_b": "831a530e-5f17-5fc8-bb0a-d5061e40196b"}, {"relation_type": "父亲", "description": "朱温为朱友雍之父。原文见907年条；不据此推导持续政治支持。", "status": "draft", "id": "398d030b-70f8-5e77-9ffe-61d0bb92180e", "person_a": "0555e455-34d4-54ef-b93e-b0e6425018ab", "person_b": "06b2387c-ba60-5cf4-888d-c776985ff0a0"}, {"relation_type": "父亲", "description": "朱温为朱友徽之父。原文见907年条；不据此推导持续政治支持。", "status": "draft", "id": "591621df-2175-52e6-be08-000bde41b042", "person_a": "0555e455-34d4-54ef-b93e-b0e6425018ab", "person_b": "693e5819-f26f-5b23-92fa-3f3c6affcf33"}, {"relation_type": "养父", "description": "朱温为朱友文养父；原文明确称养子，并说友文本康氏之子。907年受任及封王不改变养子属性。", "status": "draft", "id": "98103dc6-92bb-5e22-b001-4716a86a09d6", "person_a": "0555e455-34d4-54ef-b93e-b0e6425018ab", "person_b": "28293c54-1774-5e6d-b0a7-6ab233fcd5ec"}, {"relation_type": "兄长", "description": "朱全昱为朱温兄长；见907年改名与封王记载。", "status": "draft", "id": "25262d71-7aa3-5bf2-b9a6-8a7a408ffca4", "person_a": "4a9e8e14-490e-5b74-945b-47e8c5c92bb5", "person_b": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"relation_type": "兄长", "description": "刘守文为刘守光兄长。907年因刘守光囚父，兄弟之间发生战争；亲属关系与政治敌对分开理解。", "status": "draft", "id": "426812eb-023c-50b2-855d-bbd140afcd3f", "person_a": "8d818778-5c92-5bc7-aa3e-0a5887582536", "person_b": "ac08fec2-882c-537a-883f-b967e61fb335"}, {"relation_type": "兄长", "description": "原文称刘守奇为刘守光之弟；刘守奇在907年离开幽州。", "status": "draft", "id": "bf612689-4b45-57fc-b00f-efee050c41db", "person_a": "ac08fec2-882c-537a-883f-b967e61fb335", "person_b": "de74d9cb-822b-5499-9661-85b17cb70581"}, {"relation_type": "任用者", "description": "907年条记李克用复用张承业为监军；这里只表达该阶段的任用关系。", "status": "draft", "id": "d4fea293-65b3-5597-b943-e4c9dc19f24f", "person_a": "04af206e-fa86-581c-86b9-87a78a8d59a5", "person_b": "abe0cfa0-d9c2-52c4-8905-46bdeb978c83"}, {"relation_type": "任用者", "description": "907年敬翔受命主持崇政院，承宣旨意、顾问谋议；此处为907年的任职关系。", "status": "draft", "id": "72de0063-f86c-5081-868b-140b12786c6f", "person_a": "0555e455-34d4-54ef-b93e-b0e6425018ab", "person_b": "2d3c796e-c064-52f4-90c8-1524b6b9f0c5"}, {"relation_type": "统属者", "description": "907年十月高季昌遣其将倪可福参与攻朗州；仅据此记录当次军事统属。", "status": "draft", "id": "f2765560-7315-5edb-9629-e71b0d4b4f57", "person_a": "e1d9e2c4-6e41-5d7c-8d65-eb79a2407418", "person_b": "b23ec62e-75ea-561a-bb5f-2729974629b0"}, {"relation_type": "主君", "description": "原文明确称许玄应为弘农王腹心、常预政事；此处为907年前后的依附关系。", "status": "draft", "id": "ff3e8736-bfcb-5d46-bbe1-5a573e6678c4", "person_a": "14383d45-a8fc-53bb-9c77-7a25dcf4e06a", "person_b": "f55ed016-f45b-5faf-97f9-5d69f87f8f16"}]'::jsonb)
