SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "《通鉴》记梁王在贝州休兵。", "citation": "卷266·开平元年·第1段", "note": "原文：春，正月，辛巳，梁王休兵于贝州。；核对说明：", "status": "draft", "id": "6e51db39-4c34-5e31-b760-e1af7efb63f7", "subject_id": "00718a7a-736a-5540-a19c-ecaeb85c82e0", "source_id": "bf80b499-2fe3-5583-ac85-4b2db00de119"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "唐天祐四年正月辛巳", "citation": "卷266·开平元年·第1段", "note": "原文：春，正月，辛巳，梁王休兵于贝州。；核对说明：", "status": "draft", "id": "625b494f-3b0f-5e63-9858-e8fc5da8d3e8", "subject_id": "00718a7a-736a-5540-a19c-ecaeb85c82e0", "source_id": "bf80b499-2fe3-5583-ac85-4b2db00de119"}, {"subject_table": "event", "field_path": "start_year", "claim_text": "据开平元年条的当年叙事定位为907年；保留原纪年，不换算公历月日。", "citation": "卷266·开平元年·年次题记", "note": "原文：开平元年丁卯，公元九零七年；核对说明：", "status": "draft", "id": "abc4422e-8313-5ef3-902b-06cb430c5566", "subject_id": "00718a7a-736a-5540-a19c-ecaeb85c82e0", "source_id": "bf80b499-2fe3-5583-ac85-4b2db00de119"}, {"subject_table": "event", "field_path": "location_name", "claim_text": "贝州", "citation": "卷266·开平元年·第1段", "note": "原文：春，正月，辛巳，梁王休兵于贝州。；核对说明：", "status": "draft", "id": "f3d90865-8d68-5182-aa9d-2f4e801245a1", "subject_id": "00718a7a-736a-5540-a19c-ecaeb85c82e0", "source_id": "bf80b499-2fe3-5583-ac85-4b2db00de119"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "朱温在“梁王在贝州休兵”中的记录角色：休兵者。", "citation": "卷266·开平元年·第1段", "note": "原文：春，正月，辛巳，梁王休兵于贝州。；核对说明：", "status": "draft", "id": "d1c7f387-5603-5526-831a-3f58c3eb12e9", "subject_id": "40dfb19b-3d37-5940-9487-34212dae742b", "source_id": "bf80b499-2fe3-5583-ac85-4b2db00de119"}, {"subject_table": "event", "field_path": "description", "claim_text": "张颢、徐温率牙兵进入杨渥治事之所，杀其亲信，并逐步控制军政。诛杀三将等前事的具体日期未详。", "citation": "卷266·开平元年·第4段", "note": "原文：渥居丧，昼夜酣饮作乐，然十围之烛以击球，一烛费钱数万。或单骑出游，从者奔走道路，不知所之。左、右牙指挥使张颢、徐温泣谏，渥怒曰：“汝谓我不才，何不杀我自为之！”二人惧。渥选壮士，号“东院马军”，广署亲信为将吏；所署者恃势骄横，陵蔑勋旧。颢、温潜谋作乱。渥父行密之世，有亲军数千，营于牙城之内，渥迁出于外，以其地为射场，颢、温由是无所惮。渥之镇宣州也，命指挥使硃思勍、范思从、陈璠将亲兵三千；及嗣位，召归广陵。颢、温使三将从秦裴击江西，因戍洪州，诬以谋叛，命别将陈祐往诛之。祐间道兼行，六日至洪州，微服怀短兵径入秦裴帐中，裴大惊，祐告之故，乃召思勍等饮酒，祐数思勍等罪，执而斩之。渥闻三将死，益忌颢、温，欲诛之。丙戍，渥晨视事，颢、温帅牙兵二百，露刃直入庭中，渥曰：“尔思欲杀我邪？”对曰，“非敢然也，欲诛王左右乱政者耳！”因数渥所亲信十馀人之罪，曳下，以铁楇击杀之，谓之“兵谏”。诸将不与之同者，颢、温稍以法诛之，于是军政悉归二人，渥不能制。；核对说明：", "status": "draft", "id": "b6539daa-bd79-52f9-a878-860339131b21", "subject_id": "75b940f5-52c3-50b3-887c-2d55ad65c36c", "source_id": "bf80b499-2fe3-5583-ac85-4b2db00de119"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "唐天祐四年正月（原文干支作丙戍，待校）", "citation": "卷266·开平元年·第4段", "note": "原文：渥居丧，昼夜酣饮作乐，然十围之烛以击球，一烛费钱数万。或单骑出游，从者奔走道路，不知所之。左、右牙指挥使张颢、徐温泣谏，渥怒曰：“汝谓我不才，何不杀我自为之！”二人惧。渥选壮士，号“东院马军”，广署亲信为将吏；所署者恃势骄横，陵蔑勋旧。颢、温潜谋作乱。渥父行密之世，有亲军数千，营于牙城之内，渥迁出于外，以其地为射场，颢、温由是无所惮。渥之镇宣州也，命指挥使硃思勍、范思从、陈璠将亲兵三千；及嗣位，召归广陵。颢、温使三将从秦裴击江西，因戍洪州，诬以谋叛，命别将陈祐往诛之。祐间道兼行，六日至洪州，微服怀短兵径入秦裴帐中，裴大惊，祐告之故，乃召思勍等饮酒，祐数思勍等罪，执而斩之。渥闻三将死，益忌颢、温，欲诛之。丙戍，渥晨视事，颢、温帅牙兵二百，露刃直入庭中，渥曰：“尔思欲杀我邪？”对曰，“非敢然也，欲诛王左右乱政者耳！”因数渥所亲信十馀人之罪，曳下，以铁楇击杀之，谓之“兵谏”。诸将不与之同者，颢、温稍以法诛之，于是军政悉归二人，渥不能制。；核对说明：", "status": "draft", "id": "4c9d7da7-ce22-5291-b10c-e3dcb655c4f2", "subject_id": "75b940f5-52c3-50b3-887c-2d55ad65c36c", "source_id": "bf80b499-2fe3-5583-ac85-4b2db00de119"}, {"subject_table": "event", "field_path": "start_year", "claim_text": "据开平元年条的当年叙事定位为907年；保留原纪年，不换算公历月日。", "citation": "卷266·开平元年·年次题记", "note": "原文：开平元年丁卯，公元九零七年；核对说明：", "status": "draft", "id": "3acf32d5-68f2-5bb0-a5fe-32abec8cb5f6", "subject_id": "75b940f5-52c3-50b3-887c-2d55ad65c36c", "source_id": "bf80b499-2fe3-5583-ac85-4b2db00de119"}, {"subject_table": "person", "field_path": "description", "claim_text": "据《资治通鉴》，907年在“张颢、徐温发动兵谏，控制淮南军政”中为受制者。", "citation": "卷266·开平元年·第4段", "note": "原文：渥居丧，昼夜酣饮作乐，然十围之烛以击球，一烛费钱数万。或单骑出游，从者奔走道路，不知所之。左、右牙指挥使张颢、徐温泣谏，渥怒曰：“汝谓我不才，何不杀我自为之！”二人惧。渥选壮士，号“东院马军”，广署亲信为将吏；所署者恃势骄横，陵蔑勋旧。颢、温潜谋作乱。渥父行密之世，有亲军数千，营于牙城之内，渥迁出于外，以其地为射场，颢、温由是无所惮。渥之镇宣州也，命指挥使硃思勍、范思从、陈璠将亲兵三千；及嗣位，召归广陵。颢、温使三将从秦裴击江西，因戍洪州，诬以谋叛，命别将陈祐往诛之。祐间道兼行，六日至洪州，微服怀短兵径入秦裴帐中，裴大惊，祐告之故，乃召思勍等饮酒，祐数思勍等罪，执而斩之。渥闻三将死，益忌颢、温，欲诛之。丙戍，渥晨视事，颢、温帅牙兵二百，露刃直入庭中，渥曰：“尔思欲杀我邪？”对曰，“非敢然也，欲诛王左右乱政者耳！”因数渥所亲信十馀人之罪，曳下，以铁楇击杀之，谓之“兵谏”。诸将不与之同者，颢、温稍以法诛之，于是军政悉归二人，渥不能制。；核对说明：", "status": "draft", "id": "6782c5d1-b001-5373-b58f-6a9eb5497a33", "subject_id": "14383d45-a8fc-53bb-9c77-7a25dcf4e06a", "source_id": "bf80b499-2fe3-5583-ac85-4b2db00de119"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "杨渥在“张颢、徐温发动兵谏，控制淮南军政”中的记录角色：受制者。", "citation": "卷266·开平元年·第4段", "note": "原文：渥居丧，昼夜酣饮作乐，然十围之烛以击球，一烛费钱数万。或单骑出游，从者奔走道路，不知所之。左、右牙指挥使张颢、徐温泣谏，渥怒曰：“汝谓我不才，何不杀我自为之！”二人惧。渥选壮士，号“东院马军”，广署亲信为将吏；所署者恃势骄横，陵蔑勋旧。颢、温潜谋作乱。渥父行密之世，有亲军数千，营于牙城之内，渥迁出于外，以其地为射场，颢、温由是无所惮。渥之镇宣州也，命指挥使硃思勍、范思从、陈璠将亲兵三千；及嗣位，召归广陵。颢、温使三将从秦裴击江西，因戍洪州，诬以谋叛，命别将陈祐往诛之。祐间道兼行，六日至洪州，微服怀短兵径入秦裴帐中，裴大惊，祐告之故，乃召思勍等饮酒，祐数思勍等罪，执而斩之。渥闻三将死，益忌颢、温，欲诛之。丙戍，渥晨视事，颢、温帅牙兵二百，露刃直入庭中，渥曰：“尔思欲杀我邪？”对曰，“非敢然也，欲诛王左右乱政者耳！”因数渥所亲信十馀人之罪，曳下，以铁楇击杀之，谓之“兵谏”。诸将不与之同者，颢、温稍以法诛之，于是军政悉归二人，渥不能制。；核对说明：", "status": "draft", "id": "f294d13c-52db-54a3-8dff-6670995c78c5", "subject_id": "3ef4183a-92af-59f8-97b2-4833c7202fac", "source_id": "bf80b499-2fe3-5583-ac85-4b2db00de119"}, {"subject_table": "person", "field_path": "description", "claim_text": "据《资治通鉴》，907年在“张颢、徐温发动兵谏，控制淮南军政”中为事变组织者。", "citation": "卷266·开平元年·第4段", "note": "原文：渥居丧，昼夜酣饮作乐，然十围之烛以击球，一烛费钱数万。或单骑出游，从者奔走道路，不知所之。左、右牙指挥使张颢、徐温泣谏，渥怒曰：“汝谓我不才，何不杀我自为之！”二人惧。渥选壮士，号“东院马军”，广署亲信为将吏；所署者恃势骄横，陵蔑勋旧。颢、温潜谋作乱。渥父行密之世，有亲军数千，营于牙城之内，渥迁出于外，以其地为射场，颢、温由是无所惮。渥之镇宣州也，命指挥使硃思勍、范思从、陈璠将亲兵三千；及嗣位，召归广陵。颢、温使三将从秦裴击江西，因戍洪州，诬以谋叛，命别将陈祐往诛之。祐间道兼行，六日至洪州，微服怀短兵径入秦裴帐中，裴大惊，祐告之故，乃召思勍等饮酒，祐数思勍等罪，执而斩之。渥闻三将死，益忌颢、温，欲诛之。丙戍，渥晨视事，颢、温帅牙兵二百，露刃直入庭中，渥曰：“尔思欲杀我邪？”对曰，“非敢然也，欲诛王左右乱政者耳！”因数渥所亲信十馀人之罪，曳下，以铁楇击杀之，谓之“兵谏”。诸将不与之同者，颢、温稍以法诛之，于是军政悉归二人，渥不能制。；核对说明：", "status": "draft", "id": "9e771bd7-b18c-52d9-a892-e45031e763d2", "subject_id": "ef6aa295-919e-5b24-8849-186b807fdd8e", "source_id": "bf80b499-2fe3-5583-ac85-4b2db00de119"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "张颢在“张颢、徐温发动兵谏，控制淮南军政”